extern "C" __declspec(dllexport) int __cdecl RecoverProfile(const wchar_t* directory,char* message,int capacity){
    BuildProfile profile;std::filesystem::path selected;std::string error;
    ImageInfo image;bool ok=InspectImage(TargetPath,0x1000,image,error)&&SelectBuildProfile(directory,image.sha256,profile,selected,error);
    if(ok){AoeLocatorResult located;ok=LocateAoeImage(TargetPath,located,error,&profile)&&ValidateAoeProfile(profile,located,error);}
    if(!ok)ok=RecoverAndSaveAoeProfile(TargetPath,directory,profile,selected,error);
    if(message&&capacity>0){auto text=ok?"AOE profile ready; live validation required":error;strncpy_s(message,size_t(capacity),text.c_str(),_TRUNCATE);}
    return ok?1:0;
}
