    auto app=new App;app->safeManual=true;app->settingsPath=suiteRoot/L"settings.json";
    HWND window=CreateWindowExW(WS_EX_CONTROLPARENT,cls.lpszClassName,L"AOE Manager",WS_CHILD|WS_VISIBLE|WS_CLIPCHILDREN,0,0,1100,700,parent,nullptr,instance,app);
    if(!window)return nullptr;
    CheckDlgButton(window,StartWindows,BST_UNCHECKED);EnableWindow(GetDlgItem(window,StartWindows),FALSE);
    CheckDlgButton(window,MinimizeArm,BST_UNCHECKED);EnableWindow(GetDlgItem(window,MinimizeArm),FALSE);
    app->suiteNotice=app->Add(L"STATIC",L"ATTACH NOW ile bağlan; ardından bir normal AOE kullan.",0,SS_LEFT,app->playControls);
    ThemeSuiteControl(app->tabs);for(auto* group:{&app->researchControls,&app->profileControls,&app->playControls})for(auto control:*group)ThemeSuiteControl(control);
    TabCtrl_SetCurSel(app->tabs,2);app->ShowPage(2);ShowWindow(app->tabs,SW_HIDE);
    if(preview){KillTimer(window,1);for(auto* group:{&app->researchControls,&app->profileControls,&app->playControls})for(auto control:*group){wchar_t kind[64]{};GetClassNameW(control,kind,64);if(wcscmp(kind,L"Static")!=0)EnableWindow(control,FALSE);}}
