extern "C" __declspec(dllexport) int __cdecl ToolState(HWND window){
    auto app=reinterpret_cast<App*>(GetWindowLongPtrW(window,GWLP_USERDATA));if(!app)return 0;
    bool ready=!suitePreview&&app->validation==ProfileValidation::Valid&&app->session.active&&IsWindowEnabled(GetDlgItem(window,ArmNow));
    return (ready?1:0)|(app->continuousNxEnabled?2:0);
}
extern "C" __declspec(dllexport) int __cdecl ToggleTool(HWND window){
    auto app=reinterpret_cast<App*>(GetWindowLongPtrW(window,GWLP_USERDATA));if(!app||suitePreview)return 0;
    app->Poll();if(!(ToolState(window)&1)&&!app->continuousNxEnabled)return 0;
    CheckDlgButton(window,ArmNow,app->continuousNxEnabled?BST_UNCHECKED:BST_CHECKED);app->ToggleContinuousNx();app->Poll();return 1;
}
