extern "C" __declspec(dllexport) int __cdecl StopForSafety(HWND window){
    auto app=reinterpret_cast<App*>(GetWindowLongPtrW(window,GWLP_USERDATA));if(!app)return 1;
    app->closing=true;app->continuousNxEnabled=false;app->continuousNxManuallyDisabled=true;
    CheckDlgButton(window,AutoAttach,BST_UNCHECKED);CheckDlgButton(window,AutoArm,BST_UNCHECKED);CheckDlgButton(window,ArmNow,BST_UNCHECKED);
    KillTimer(window,1);return 1; // Quiesce only; restore/detach runs at its ordered turn.
}
extern "C" __declspec(dllexport) int __cdecl CloseTool(HWND window){
    if(!IsWindow(window))return 1;
    auto app=reinterpret_cast<App*>(GetWindowLongPtrW(window,GWLP_USERDATA));
    if(!app)return 0;
    StopForSafety(window);
    if(!app->suiteCloseStarted){
        if(!app->RestoreVisual("suite_shutdown",false))return 0;
        CheckDlgButton(window,HideAoeVisual,BST_UNCHECKED);
        app->tracer.detach();app->suiteCloseStarted=true;
    }
    // Never enter Tracer::~Tracer's blocking join on the WinForms UI thread.
    // The worker keeps its ownership state and retries failed restoration itself.
    if(!app->tracer.detachComplete())return -1;
    DestroyWindow(window);return IsWindow(window)?0:1;
}
